9	/**
10	 * Rejects a create request whose city already contains {@value #CAPACITY} or more owners
11	 * (compared case-insensitively). At or above capacity rejects 409.
12	 */
13	public class RequireCityCapacity {
14	
15	    private static final int CAPACITY = 50;
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws CityAtCapacityException {
19	        String city = request.getCity();
20	        long count = ownerRepository.findAll().stream()
21	                .filter(owner -> city != null && city.equalsIgnoreCase(owner.getCity()))
22	                .count();
23	        if (count >= CAPACITY) {
24	            throw new CityAtCapacityException(city);
25	        }
26	    }
27	}
