package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;
import java.time.LocalDate;
import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");

    private static final AtomicLong SEQ = new AtomicLong();

    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        LocalDate today = BusinessDay.roll(LocalDate.now());
        long createdToday = ownerRepository.findAll().stream()
                .filter(other -> today.equals(other.getRegistrationDate())).count();
        dto.setBulkSignupWarning(createdToday > 80);
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), dto.getMembershipLevel(),
                dto.getMembershipNumber());
        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
                SEQ.incrementAndGet(), owner.getId(), owner.getCustomerCode(), dto.getMembershipLevel());
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Soft-match flag: a create that has already cleared the hard identity guard but whose
 * {@code identityKey} still differs from an existing owner sharing its {@code soundex(lastName)}
 * and postcode is recorded as a possible duplicate. Sets {@code possibleDuplicate} true and
 * {@code possibleDuplicateOf} to that owner's id, otherwise false. A declared household member
 * ({@code sharesHousehold} true) is never a suspected duplicate.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicate(false);
            return;
        }
        String soundex = Soundex.of(owner.getLastName());
        String postcode = normalize(owner.getPostcode());
        String key = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
        for (Owner other : ownerRepository.findAll()) {
            if (!postcode.isEmpty() && soundex.equals(Soundex.of(other.getLastName()))
                    && postcode.equals(normalize(other.getPostcode()))
                    && !key.equals(OwnerIdentity.key(other.getTelephone(), other.getEmail(), other.getLastName()))) {
                owner.setPossibleDuplicate(true);
                owner.setPossibleDuplicateOf(other.getId());
                return;
            }
        }
        owner.setPossibleDuplicate(false);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Caps the new owner's membershipLevel at one above the highest membershipLevel among the existing
 * members of their household (same computed {@code householdId}, see {@link HouseholdId}). With no
 * existing household member the natural level stands, i.e. no cap applies.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper) {
        String household = HouseholdId.of(owner.getLastName(), owner.getPostcode());
        int highest = ownerRepository.findAll().stream()
                .filter(other -> household.equals(HouseholdId.of(other.getLastName(), other.getPostcode())))
                .mapToInt(ownerMapper::membershipLevel)
                .max().orElse(-1);
        if (highest < 0) {
            return;
        }
        int natural = MembershipPoints.level(MembershipPoints.of(owner));
        owner.setMembershipLevel(Math.min(natural, highest + 1));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners belong to this owner's household (same computed {@code householdId} —
 * last name and postcode, see {@link HouseholdId}) after this create, i.e. the existing members
 * plus the new owner. Drives the 'GOLD' membership tier.
 */
public class CountHousehold {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String household = HouseholdId.of(owner.getLastName(), owner.getPostcode());
        long existing = ownerRepository.findAll().stream()
                .filter(other -> household.equals(HouseholdId.of(other.getLastName(), other.getPostcode())))
                .count();
        owner.setHouseholdCount((int) existing + 1);
    }
}

